const q2m_move_set *q2m_moves_named(const char *key)
{
    if (key == NULL) return NULL;
    for (size_t i=0;i<sizeof(move_sets)/sizeof(move_sets[0]);++i)
        if (strcmp(move_sets[i].key,key)==0) return &move_sets[i];
    return NULL;
}
